import assert from 'node:assert/strict'
import test from 'node:test'
import { summarizeTags } from './example.js'

// Independent table: results are stated directly, not generated by summarizeTags.
const examples = [
  { input: ['JS', 'js', 'Python'], counts: [['js', 2], ['python', 1]], uniqueTags: ['js', 'python'] },
  { input: [' CSS ', 'css', 'HTML'], counts: [['css', 2], ['html', 1]], uniqueTags: ['css', 'html'] },
  { input: [], counts: [], uniqueTags: [] },
]

test('groups case-normalized tags against the independent expected table', () => {
  for (const example of examples) {
    const actual = summarizeTags(example.input)
    assert.deepEqual([...actual.counts], example.counts)
    assert.deepEqual(actual.uniqueTags, example.uniqueTags)
  }
})

test('rejects inputs that are not arrays of tags', () => {
  assert.throws(() => summarizeTags('JS'), TypeError)
  assert.throws(() => summarizeTags(['JS', 2]), TypeError)
})
